var DELIBERATE_MS = 400;

class FocusGuard {
  #lastInput = Number.NEGATIVE_INFINITY;
  #released = false;
  input(now) {
    this.#lastInput = now;
  }
  get released() {
    return this.#released;
  }
  moved(now, inside) {
    if (inside) {
      this.#released = false;
      return false;
    }
    if (this.#released)
      return false;
    if (now - this.#lastInput < DELIBERATE_MS) {
      this.#released = true;
      return false;
    }
    return true;
  }
  reclaim() {
    this.#released = false;
  }
}

